INSERT INTO public.market_rules (category, name, description, jurisdiction, effective_date, expiry_date, rule_logic, impact_description, is_active, id, created_at, updated_at) VALUES ('IMPORT_ELIGIBILITY', 'US 25-Year Import Exemption', 'Vehicles 25+ years old are exempt from FMVSS standards for US import under 49 USC 30112(b)(9). Opens the world''s largest collector car buyer pool.', 'US', '1998-01-01', NULL, '{"type": "age_threshold", "exemption": "FMVSS", "threshold_years": 25}', 'Typically adds 15-30% to market value by opening US buyer pool for previously ineligible non-US-spec vehicles.', true, '368b1802-eb82-46e2-8991-eef84937fd23', '2026-08-16 17:36:23.367062+00', '2026-08-16 17:36:23.367062+00') ON CONFLICT DO NOTHING;
INSERT INTO public.market_rules (category, name, description, jurisdiction, effective_date, expiry_date, rule_logic, impact_description, is_active, id, created_at, updated_at) VALUES ('CERTIFICATION', 'Ferrari Classiche Certification', 'Official Ferrari certification programme verifying originality and provenance. Red Book certification adds quantifiable value, typically 5-15% premium.', NULL, NULL, NULL, '{"type": "certification", "provider": "Ferrari Classiche", "premium_pct_range": [5, 15]}', 'Classiche-certified cars command 5-15% premium over uncertified equivalents. Required for concours eligibility.', true, 'b97940e4-19b2-4269-9181-3bb3fc19f407', '2026-08-16 17:36:23.367062+00', '2026-08-16 17:36:23.367062+00') ON CONFLICT DO NOTHING;
INSERT INTO public.market_rules (category, name, description, jurisdiction, effective_date, expiry_date, rule_logic, impact_description, is_active, id, created_at, updated_at) VALUES ('DRIVE_SIDE', 'LHD/RHD Market Premium Differential', 'Left-hand drive commands premium in US/EU markets. RHD is neutral in UK/Australia/Japan but discounted 5-15% in LHD markets.', NULL, NULL, NULL, '{"type": "drive_side_differential", "lhd_premium_markets": ["US", "EU", "UAE"], "rhd_neutral_markets": ["UK", "Australia", "Japan", "Singapore", "Hong Kong"], "rhd_discount_in_lhd_market_pct": -10}', 'A RHD car in the US is worth 5-15% less than LHD equivalent. No discount in RHD markets.', true, 'de20cfd9-2121-4aef-b78a-50962dabb7a1', '2026-08-16 17:36:23.367062+00', '2026-08-16 17:36:23.367062+00') ON CONFLICT DO NOTHING;
INSERT INTO public.market_rules (category, name, description, jurisdiction, effective_date, expiry_date, rule_logic, impact_description, is_active, id, created_at, updated_at) VALUES ('TAX_TREATMENT', 'UK VAT on Margin Scheme', 'UK dealers can sell collector cars under VAT margin scheme — VAT charged only on dealer margin, not full price. UAE has no VAT on vehicles.', 'UK', NULL, NULL, '{"type": "tax", "vat_rate": 20, "margin_scheme_eligible": true}', 'Effective VAT cost is lower under margin scheme. UAE purchases avoid VAT entirely.', true, '8f7b8e7d-60f6-4f00-8567-54d4a363745d', '2026-08-16 17:36:23.367062+00', '2026-08-16 17:36:23.367062+00') ON CONFLICT DO NOTHING;
